from fastapi import FastAPI, Form
from fastapi.responses import HTMLResponse, JSONResponse
from app.planner import make_plan
from app.providers import submit, poll

app = FastAPI(title="Solvent Video Agent")

INDEX='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solvent Video Agent</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:#090b10;color:#f3f5f7}main{max-width:1100px;margin:auto;padding:40px 20px 80px}.brand{font-weight:800;letter-spacing:.04em}.dot{display:inline-block;width:13px;height:13px;border-radius:50%;background:#26e6ff;box-shadow:0 0 28px #26e6ff;margin-right:10px}.hero{padding:55px 0 25px}h1{font-size:clamp(44px,7vw,82px);line-height:.94;letter-spacing:-.06em;margin:0 0 18px}.muted{color:#9298a6;max-width:760px;font-size:18px}.panel{background:linear-gradient(180deg,#11151e,#0d1118);border:1px solid #242a36;border-radius:22px;padding:22px;margin-top:20px}textarea,input,select{width:100%;background:#090c12;color:white;border:1px solid #2a3240;border-radius:14px;padding:14px;font:inherit}textarea{min-height:130px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}button{background:#e9fbff;color:#071014;border:0;border-radius:14px;padding:14px 18px;font-weight:800;cursor:pointer}.secondary{background:#161d28;color:#dbe7eb;border:1px solid #2a3443}.free{border:1px solid #245b63;background:#0c2025;border-radius:16px;padding:16px;margin-top:14px}.scene{border-top:1px solid #252c38;padding:20px 0}.prompt{white-space:pre-wrap;color:#c8d0d8;background:#0a0d13;border-radius:12px;padding:13px;margin:10px 0}.pill{display:inline-block;padding:6px 9px;border:1px solid #2c3744;border-radius:999px;color:#97a8b7;font-size:12px;margin:3px}.status{margin-top:12px;color:#7deaf6}.video{width:100%;max-width:360px;border-radius:14px;margin-top:12px;background:#05070a}.tiny{font-size:12px;color:#7f8998;margin-top:8px}.ok{color:#79e6a4}.err{color:#ff8f8f}.keybox{display:none}@media(max-width:700px){.row{grid-template-columns:1fr}}</style></head><body><main><div class="brand"><span class="dot"></span>SOLVENT VIDEO AGENT · v2.3</div><section class="hero"><h1>Free generation.<br>Inside Solvent.</h1><p class="muted">The free route now calls Lightricks LTX Video Fast on Hugging Face ZeroGPU directly from your browser and returns the finished clip into this page.</p></section><div class="panel"><label>Video engine</label><select id="provider" onchange="providerChanged()"><option value="free">Free Experimental · LTX ZeroGPU</option><option value="fal_wan">Wan via fal · paid GPU</option><option value="pixverse">PixVerse V6 · paid API</option></select><div id="keybox" class="keybox"><label id="keyLabel">API key</label><input id="apiKey" type="password" placeholder="Paste key for selected paid engine"></div><div id="engineNote" class="free"><b>No API key required</b><br><span class="tiny">Public shared Hugging Face ZeroGPU. Queues and anonymous daily quota apply, so availability is best-effort rather than guaranteed.</span></div></div><div class="panel"><label>What should we create?</label><textarea id="idea">Your UX might not be the problem. Show how deeper business problems become visible through the interface.</textarea><div class="row"><select id="duration"><option value="30">30 seconds</option><option value="45">45 seconds</option><option value="60">60 seconds</option></select><button onclick="generatePlan()">✦ Generate Video Plan</button></div><div id="status" class="status"></div></div><div id="result" class="panel" style="display:none"></div><script>let plan=null;const LTX='https://lightricks-ltx-video-distilled.hf.space';function providerChanged(){const f=provider.value==='free';keybox.style.display=f?'none':'block';keyLabel.textContent=provider.value==='pixverse'?'PixVerse API key':'fal API key';engineNote.style.display=f?'block':'none'}async function generatePlan(){status.textContent='Building continuity map…';const body=new URLSearchParams({idea:idea.value,duration:duration.value});const r=await fetch('/plan',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});plan=await r.json();let html=`<h2>${plan.title}</h2><p><b>${plan.hook}</b></p><p class="muted">${plan.narration}</p><div>${plan.continuity_rules.map(x=>`<span class="pill">${x}</span>`).join('')}</div>`;for(const s of plan.scenes){html+=`<div class="scene"><h3>Scene ${s.id} · ${s.purpose}</h3><small>${s.duration}s · ${s.camera}</small><div class="prompt" id="p${s.id}">${s.prompt}</div><div class="row"><button class="secondary" onclick="copyPrompt(${s.id})">Copy prompt</button><button onclick="provider.value==='free'?freeScene(${s.id}):generateScene(${s.id})">${provider.value==='free'?'Generate Free':'Generate Scene'}</button></div><div id="sceneStatus${s.id}" class="status"></div><div id="video${s.id}"></div></div>`}html+=`<button onclick="downloadManifest()">Export Manifest</button>`;result.innerHTML=html;result.style.display='block';status.textContent='Plan ready.'}async function copyPrompt(id){await navigator.clipboard.writeText(document.getElementById('p'+id).innerText);document.getElementById('sceneStatus'+id).textContent='Prompt copied.'}function findUrl(x){if(typeof x==='string'&&x.includes('http'))return x;if(Array.isArray(x)){for(const v of x){const u=findUrl(v);if(u)return u}}if(x&&typeof x==='object'){if(typeof x.url==='string')return x.url;for(const v of Object.values(x)){const u=findUrl(v);if(u)return u}}return null}async function freeScene(id){const s=plan.scenes.find(x=>x.id===id),el=document.getElementById('sceneStatus'+id);el.className='status';el.textContent='Submitting to free LTX ZeroGPU…';const neg='low quality, blurry, text, watermark, logo, subtitles, flicker, jump cut, scene reset, deformed geometry';const data=[s.prompt,neg,null,null,768,448,'text-to-video',2.0,9,42,true,3.0,false];try{const q=await fetch(LTX+'/gradio_api/call/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data})});if(!q.ok)throw new Error('Free worker rejected the request ('+q.status+').');const j=await q.json();if(!j.event_id)throw new Error('No queue id returned.');el.textContent='Queued on shared ZeroGPU…';const stream=await fetch(LTX+'/gradio_api/call/generate/'+j.event_id);if(!stream.ok)throw new Error('Could not read ZeroGPU queue.');const reader=stream.body.getReader(),dec=new TextDecoder();let buf='';while(true){const {done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});const blocks=buf.split('\n\n');buf=blocks.pop();for(const b of blocks){const dm=b.match(/data:\s*(.*)/s);if(!dm)continue;let payload;try{payload=JSON.parse(dm[1])}catch{continue}const u=findUrl(payload);if(u){el.className='status ok';el.textContent='Free scene ready.';document.getElementById('video'+id).innerHTML=`<video class="video" controls playsinline src="${u}"></video><p><a href="${u}" target="_blank">Open generated clip</a></p>`;return}if(b.includes('error'))throw new Error('ZeroGPU generation failed.')}}}throw new Error('Generation ended without a video URL.')}catch(e){el.className='status err';el.innerHTML=e.message+'<br><span class="tiny">The shared worker may be busy, your anonymous quota may be exhausted, or Hugging Face may have changed the Space API. Try again later or switch engine.</span>'}}async function generateScene(id){const key=apiKey.value.trim(),p=provider.value;if(!key){alert('Add an API key for the selected paid engine first.');return}const s=plan.scenes.find(x=>x.id===id),el=document.getElementById('sceneStatus'+id);el.className='status';el.textContent='Submitting…';const body=new URLSearchParams({provider:p,api_key:key,prompt:s.prompt,duration:'5'});const r=await fetch('/generate',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),d=await r.json();if(!r.ok||!d.job_id){el.className='status err';el.textContent=d.error||'Generation failed.';return}el.textContent='Rendering…';pollScene(id,key,d)}async function pollScene(id,key,job){const el=document.getElementById('sceneStatus'+id);for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,5000));const body=new URLSearchParams({provider:job.provider,api_key:key,job_id:job.job_id||'',status_url:job.status_url||'',response_url:job.response_url||''});const r=await fetch('/result',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),d=await r.json();if(d.done&&d.url){el.className='status ok';el.textContent='Scene ready.';document.getElementById('video'+id).innerHTML=`<video class="video" controls playsinline src="${d.url}"></video>`;return}if(d.error){el.className='status err';el.textContent=d.error;return}el.textContent='Rendering · '+(d.status||((i+1)*5+'s'))}}function downloadManifest(){const b=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='solvent-video-manifest.json';a.click()}</script></main></body></html>'''

@app.get('/',response_class=HTMLResponse)
def home(): return INDEX

@app.post('/plan')
def plan(idea:str=Form(...),duration:int=Form(30)): return JSONResponse(make_plan(idea,duration))

@app.post('/generate')
def generate(provider:str=Form(...),api_key:str=Form(...),prompt:str=Form(...),duration:int=Form(5)):
    try: return submit(provider,api_key,prompt,duration)
    except Exception as e: return JSONResponse({'error':str(e)},status_code=400)

@app.post('/result')
def result(provider:str=Form(...),api_key:str=Form(...),job_id:str=Form(''),status_url:str=Form(''),response_url:str=Form('')):
    try: return poll(provider,api_key,job_id,status_url,response_url)
    except Exception as e: return JSONResponse({'error':str(e)},status_code=400)

@app.get('/health')
def health(): return {'ok':True,'service':'solvent-video-agent','version':'2.3','free_engine':'Lightricks LTX Video Fast / Hugging Face ZeroGPU','paid_providers':['fal_wan','pixverse']}
